  "brief": {
    "title": "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems",
    "one_liner": "SkillClaw enables LLM agent skills to continuously evolve by aggregating cross-user interaction trajectories and applying agentic, evidence-driven skill updates.",
    "goal": "The audience should understand the SkillClaw framework architecture, its collective evolution loop, the agentic evolver pipeline, and experimental evidence showing that multi-user trajectory aggregation drives meaningful skill improvement."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "SkillClaw: Let Skills Evolve Collectively with Agentic Evolver",
      "objective": "Cover slide with paper title and key tagline about collective skill evolution in multi-user agent ecosystems. Reference the source (arxiv.org/abs/2604.08377) and include the architecture overview figure (figure_1.jpg) as a background or hero image."
    },
    {
      "id": "problem-static-skills",
      "title": "Agent Skills Remain Static After Deployment — Users Rediscover Solutions Independently",
      "objective": "Explain the core problem: current LLM agent skills are manually installed and never updated from runtime experience. Failures and solutions are rediscovered repeatedly across users. Use a simple diagram or bullet points contrasting static vs. evolving skill paradigms."
    },
    {
      "id": "skillclaw-architecture-overview",
      "title": "Closed-Loop Pipeline: From Multi-User Interaction to Shared Skill Evolution",
      "objective": "Present the full SkillClaw architecture using the overview figure (figure_1.jpg). Show the loop: multi-user interaction → session collection → agentic evolver → skill synchronization. Highlight the four stages: Evidence, Attribution, Evolution, and Distribution."
    },
    {
      "id": "agentic-evolver-pipeline",
      "title": "Agentic Evolver: Evidence → Attribution → Evolution in Three Stages",
      "objective": "Detail the three-stage agentic workflow inside the evolver: (1) Evidence analysis of trajectories, (2) Attribution to diagnose root causes, (3) Evolution to propose skill mutations. Emphasize that this is open-ended agent reasoning, not predefined rules."
    },
    {
      "id": "multi-user-aggregation",
      "title": "Cross-User Trajectory Aggregation Exposes Skill Behavioral Boundaries",
      "objective": "Explain how trajectories from different users across compatible Claw-style systems (OpenClaw, CoPaw, IronClaw, PicoClaw, ZeroClaw, NanoClaw, NemoClaw) exercising the same skill under diverse contexts produce complementary signals — success patterns and failure modes. Highlight that a single user rarely generates enough signal to separate a generalizable improvement from an idiosyncratic fix. Reference the group session aggregation portion of the architecture figure."
    },
    {
      "id": "evolution-case-study-creative",
      "title": "Case Study: Multimodal Creative Pipeline Skill — 6 Days of Evolution Attempts",
      "objective": "Present the day-by-day evolution log for the multimodal creative task pipeline as a table. Show how the validator accepted/rejected candidates and how the skill pool was maintained. Highlight that only 1 of 6 candidates was accepted, illustrating the conservative verification process."
    },
    {
      "id": "evolution-case-study-git",
      "title": "Case Study: Git Push Auth-Fallback Skill — Iterative Refinement Over 6 Days",
      "objective": "Present the second evolution log table for the git-push-with-auth-fallback skill. Contrast with the creative pipeline case: here 3 of 6 days yielded accepted updates, showing successful iterative refinement. Use a table visualization."
    },
    {
      "id": "takeaways-implications",
      "title": "Key Takeaways: Three Properties That Distinguish SkillClaw from Existing Systems",
      "objective": "Summarize the three distinguishing properties: (1) Collective evolution — individual interactions improve a shared ecosystem, (2) Fully automatic — no manual curation needed, (3) Agentic evolution paradigm — open-ended reasoning over evidence. End with implications for building continuously improving agent systems."
    }
  ]
}

