const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Color palette: Deep navy + ice blue + teal accent (technical/research feel)
const C = {
  navy:    "0D1B2A",   // dominant dark background
  midBlue: "1A3A5C",   // secondary panel
  teal:    "0D9488",   // accent / highlight
  ice:     "CAE8F8",   // light text / headings on dark
  white:   "FFFFFF",
  offWhite:"F0F6FC",
  muted:   "94A3B8",
  green:   "16A34A",   // accepted
  red:     "DC2626",   // rejected
  amber:   "D97706",
  slate:   "334155",
  slateLight: "E2EBF6",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.18 });

// ─── SLIDE 1: Title Slide ────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };

  // Background image (figure_1.jpg) as faint hero, right half
  sl.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 4.8, y: 0.4, w: 5.0, h: 4.8,
    transparency: 30,
  });

  // Teal left accent bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.0, w: 0.1, h: 3.3,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Title
  sl.addText("SkillClaw", {
    x: 0.75, y: 0.95, w: 5.8, h: 0.75,
    fontSize: 44, bold: true, color: C.white, fontFace: "Calibri",
    margin: 0
  });

  sl.addText("Collective Skill Evolution for\nMulti-User LLM Agent Ecosystems", {
    x: 0.75, y: 1.75, w: 5.8, h: 1.2,
    fontSize: 22, bold: false, color: C.ice, fontFace: "Calibri",
    margin: 0
  });

  // Tagline
  sl.addText("Skills that learn from every user. Automatically.", {
    x: 0.75, y: 3.1, w: 5.8, h: 0.55,
    fontSize: 15, italic: true, color: C.teal, fontFace: "Calibri",
    margin: 0
  });

  // Source
  sl.addText("arxiv.org/abs/2604.08377", {
    x: 0.75, y: 4.9, w: 5.0, h: 0.35,
    fontSize: 11, color: C.muted, fontFace: "Calibri",
    margin: 0
  });

  // Audience tag pill
  sl.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.75, y: 3.8, w: 3.2, h: 0.38,
    fill: { color: C.midBlue }, line: { color: C.teal, width: 1 }, rectRadius: 0.05
  });
  sl.addText("ML Researchers · AI Systems Engineers", {
    x: 0.75, y: 3.8, w: 3.2, h: 0.38,
    fontSize: 10, color: C.ice, align: "center", valign: "middle", fontFace: "Calibri",
    margin: 0
  });
}

// ─── SLIDE 2: Problem — Static Skills ───────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

  // Top bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.65,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  sl.addText("PROBLEM", {
    x: 0.5, y: 0, w: 9, h: 0.65,
    fontSize: 11, color: C.teal, bold: true, valign: "middle", fontFace: "Calibri",
    charSpacing: 3, margin: 0
  });

  sl.addText("Agent Skills Remain Static After Deployment", {
    x: 0.5, y: 0.75, w: 9, h: 0.7,
    fontSize: 28, bold: true, color: C.navy, fontFace: "Calibri", margin: 0
  });

  sl.addText("Users Rediscover Solutions Independently", {
    x: 0.5, y: 1.45, w: 9, h: 0.45,
    fontSize: 17, color: C.slate, fontFace: "Calibri", italic: true, margin: 0
  });

  // Two columns: Static vs Evolving
  const colY = 2.05;
  const colH = 2.95;

  // Static column
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: colY, w: 4.1, h: colH,
    fill: { color: "F8D7DA" }, line: { color: "DC2626", width: 1.5 },
    shadow: makeShadow()
  });
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: colY, w: 4.1, h: 0.42,
    fill: { color: C.red }, line: { color: C.red }
  });
  sl.addText("STATIC SKILL ECOSYSTEM", {
    x: 0.5, y: colY, w: 4.1, h: 0.42,
    fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle", fontFace: "Calibri", margin: 0
  });
  sl.addText([
    { text: "Skills manually installed from hub", options: { bullet: true, breakLine: true } },
    { text: "No updates from runtime experience", options: { bullet: true, breakLine: true } },
    { text: "Failures repeat across users", options: { bullet: true, breakLine: true } },
    { text: "Each user rediscovers same solutions", options: { bullet: true, breakLine: true } },
    { text: "Knowledge never accumulates at system level", options: { bullet: true } },
  ], {
    x: 0.65, y: colY + 0.55, w: 3.8, h: 2.3,
    fontSize: 13, color: C.slate, fontFace: "Calibri"
  });

  // Arrow
  sl.addShape(pres.shapes.LINE, {
    x: 4.7, y: colY + colH / 2 - 0.02, w: 0.6, h: 0,
    line: { color: C.teal, width: 2.5 }
  });
  sl.addText("→", {
    x: 4.7, y: colY + colH / 2 - 0.28, w: 0.6, h: 0.5,
    fontSize: 22, color: C.teal, align: "center", fontFace: "Calibri", margin: 0
  });

  // Evolving column
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 5.4, y: colY, w: 4.1, h: colH,
    fill: { color: "E6F7F1" }, line: { color: C.teal, width: 1.5 },
    shadow: makeShadow()
  });
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 5.4, y: colY, w: 4.1, h: 0.42,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  sl.addText("EVOLVING SKILL ECOSYSTEM", {
    x: 5.4, y: colY, w: 4.1, h: 0.42,
    fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle", fontFace: "Calibri", margin: 0
  });
  sl.addText([
    { text: "Skills evolve from runtime interactions", options: { bullet: true, breakLine: true } },
    { text: "Cross-user knowledge aggregation", options: { bullet: true, breakLine: true } },
    { text: "Patterns of failure → system improvements", options: { bullet: true, breakLine: true } },
    { text: "Solutions shared across the ecosystem", options: { bullet: true, breakLine: true } },
    { text: "Continuous, automatic skill refinement", options: { bullet: true } },
  ], {
    x: 5.55, y: colY + 0.55, w: 3.8, h: 2.3,
    fontSize: 13, color: C.slate, fontFace: "Calibri"
  });

  // Bottom note
  sl.addText("Memory methods store instances but don't generalize. Skill libraries compress experience but remain static.", {
    x: 0.5, y: 5.15, w: 9, h: 0.35,
    fontSize: 11, italic: true, color: C.muted, fontFace: "Calibri", margin: 0
  });
}

// ─── SLIDE 3: Architecture Overview ─────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };

  // Top bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.6,
    fill: { color: C.midBlue }, line: { color: C.midBlue }
  });
  sl.addText("ARCHITECTURE", {
    x: 0.5, y: 0, w: 9, h: 0.6,
    fontSize: 11, color: C.teal, bold: true, valign: "middle", fontFace: "Calibri",
    charSpacing: 3, margin: 0
  });

  sl.addText("Closed-Loop Pipeline: Multi-User Interaction → Shared Skill Evolution", {
    x: 0.5, y: 0.68, w: 9, h: 0.55,
    fontSize: 22, bold: true, color: C.white, fontFace: "Calibri", margin: 0
  });

  // Architecture figure
  sl.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 1.35, w: 5.5, h: 3.5,
  });

  // Four stage boxes on the right
  const stages = [
    { label: "1  EVIDENCE",     desc: "Analyze trajectories\nIdentify behavioral patterns",    color: "1A6B8A" },
    { label: "2  ATTRIBUTION",  desc: "Diagnose root causes\nof failures & successes",           color: "117A5A" },
    { label: "3  EVOLUTION",    desc: "Propose skill mutations\nRefine or create skills",        color: "7A4A11" },
    { label: "4  DISTRIBUTION", desc: "Verify & merge updates\nSync back to all agents",         color: "6B1A6B" },
  ];

  stages.forEach((s, i) => {
    const y = 1.35 + i * 0.88;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y, w: 3.3, h: 0.78,
      fill: { color: s.color }, line: { color: C.teal, width: 0.5 },
      shadow: makeShadow()
    });
    sl.addText(s.label, {
      x: 6.38, y: y + 0.04, w: 3.1, h: 0.28,
      fontSize: 11, bold: true, color: C.ice, fontFace: "Calibri", margin: 0
    });
    sl.addText(s.desc, {
      x: 6.38, y: y + 0.32, w: 3.1, h: 0.42,
      fontSize: 10, color: C.white, fontFace: "Calibri", margin: 0
    });
  });

  // Connecting arrow between stage boxes
  for (let i = 0; i < 3; i++) {
    sl.addShape(pres.shapes.LINE, {
      x: 7.95, y: 1.35 + i * 0.88 + 0.78, w: 0, h: 0.1,
      line: { color: C.teal, width: 1.5 }
    });
  }

  // Loop label
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 5.1, w: 3.3, h: 0.35,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  sl.addText("CLOSED LOOP — CONTINUOUS IMPROVEMENT", {
    x: 6.3, y: 5.1, w: 3.3, h: 0.35,
    fontSize: 9, bold: true, color: C.white, align: "center", valign: "middle", fontFace: "Calibri", margin: 0
  });
}

// ─── SLIDE 4: Agentic Evolver Pipeline ──────────────────────────────────────
{
  const sl = pres.addSlide();
