      shadow: makeShadow()
    });
    // Accent top bar
    sl.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.82, w: 2.9, h: 0.08,
      fill: { color: s.accent }, line: { color: s.accent }
    });
    // Number badge
    sl.addShape(pres.shapes.OVAL, {
      x: x + 0.1, y: 1.95, w: 0.52, h: 0.52,
      fill: { color: s.accent }, line: { color: s.accent }
