    x: 0.4, y: 4.28, w: 9.2, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  sl.addText("Implications", {
    x: 0.4, y: 4.38, w: 2.0, h: 0.32,
    fontSize: 13, bold: true, color: C.teal, fontFace: "Calibri", margin: 0
  });

  sl.addText([
    { text: "Continuously improving agent systems require collective, cross-user evidence — not just per-session memory.  ", options: { breakLine: true } },
    { text: "Evaluation on WildClawBench (Qwen3-Max backbone) demonstrates substantial improvements across tasks.", options: {} },
  ], {
    x: 0.4, y: 4.73, w: 9.2, h: 0.75,
    fontSize: 11.5, color: C.ice, fontFace: "Calibri", margin: 0
