      x: x + 0.1, y: 2.72, w: 2.7, h: 2.45,
      fontSize: 11, color: C.white, fontFace: "Calibri"
    });
  });

  // Bottom note
  sl.addText("The evolver performs open-ended reasoning over interaction evidence — no hard-coded update logic.", {
    x: 0.5, y: 5.38, w: 9, h: 0.22,
    fontSize: 10, italic: true, color: C.muted, fontFace: "Calibri", margin: 0
  });
}

// ─── SLIDE 5: Cross-User Trajectory Aggregation ──────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };

  // Top bar
