  sl.addText("Multimodal Creative Pipeline Skill — 6 Days of Evolution", {
    x: 0.5, y: 0.68, w: 9, h: 0.55,
    fontSize: 24, bold: true, color: C.navy, fontFace: "Calibri", margin: 0
