  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.3, w: 4.3, h: 0.5,
    fill: { color: "FEF3C7" }, line: { color: C.amber, width: 1.5 }
  });
  sl.addText("Conservative verification: only 1 of 6 candidates accepted", {
    x: 0.6, y: 1.3, w: 4.1, h: 0.5,
    fontSize: 12, bold: true, color: C.slate, valign: "middle", fontFace: "Calibri", margin: 0
  });

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.3, w: 4.4, h: 0.5,
    fill: { color: "E6F7F1" }, line: { color: C.teal, width: 1 }
  });
