  const tableData = [
    [
      { text: "Day", options: { bold: true, color: C.white, fill: { color: C.navy }, align: "center" } },
      { text: "Candidate Skill", options: { bold: true, color: C.white, fill: { color: C.navy } } },
      { text: "Skill Function", options: { bold: true, color: C.white, fill: { color: C.navy } } },
      { text: "Verdict", options: { bold: true, color: C.white, fill: { color: C.navy }, align: "center" } },
      { text: "Next-Day Action", options: { bold: true, color: C.white, fill: { color: C.navy } } },
    ],
    [
      { text: "1", options: { align: "center", bold: true } },
      { text: "validate-tmp-workspace-inputs" },
      { text: "Check /tmp_workspace inputs & environment setup" },
      { text: "ACCEPT", options: { bold: true, color: C.green, align: "center" } },
      { text: "Upgrade to new best pool" },
    ],
    [
      { text: "2", options: { align: "center" } },
      { text: "multimodal-input-validation-and-setup" },
      { text: "Multimodal input validation & output env init" },
      { text: "REJECT", options: { bold: true, color: C.red, align: "center" } },
      { text: "Keep current best pool" },
    ],
    [
      { text: "3", options: { align: "center" } },
      { text: "multimodal-creative-task-pipeline" },
      { text: "Multimodal creative pipeline (extract from PDF/video/image)" },
      { text: "REJECT", options: { bold: true, color: C.red, align: "center" } },
      { text: "Keep current best pool" },
